import os, re, subprocess, sys

def git_z(*args):
    return subprocess.run(['git', *args, '-z'], check=True, stdout=subprocess.PIPE).stdout.decode('utf-8', 'surrogateescape').split('\0')

tracked = [p for p in git_z('ls-files') if p]
mapping_files = [p for p in tracked if p.endswith('renames.conf')]
if not mapping_files:
    sys.exit('no tracked renames.conf found')

mappings = []
for mf in mapping_files:
    with open(mf, 'r', encoding='utf-8', errors='surrogateescape') as f:
        for line in f:
            line = line.split('#', 1)[0].strip()
            if '=' not in line:
                continue
            old, new = line.split('=', 1)
            old, new = old.strip(), new.strip()
            if old and new and old != new:
                mappings.append((old, new))
if not mappings:
    sys.exit('no rename mappings found')

# Longest old key first, to avoid prefix collisions.
mappings.sort(key=lambda x: len(x[0]), reverse=True)
replacement = dict()
for old, new in mappings:
    if old not in replacement:
        replacement[old] = new

ignored = [p for p in git_z('ls-files', '--others', '--ignored', '--exclude-standard') if p]
if not ignored:
    sys.exit('no ignored untracked files')

changed = 0
for path in ignored:
    try:
        with open(path, 'r', encoding='utf-8', errors='surrogateescape', newline='') as f:
            text = f.read()
    except (OSError, UnicodeDecodeError):
        continue

    lines = text.splitlines(keepends=True)
    entries = []
    for i, line in enumerate(lines):
        m = re.match(r'^([ \t]*)([^=\s][^=]*?)([ \t]*=[ \t]*)(.*)$', line, re.S)
        if m:
            indent, key, eq, rest = m.groups()
            entries.append((i, indent, key.strip(), eq, rest, line))
        else:
            entries.append((i, None, None, None, None, line))

    present_keys = set(entry[2] for entry in entries if entry[2] is not None)
    new_lines = []
    for i, indent, key, eq, rest, line in entries:
        if key is not None and key in replacement:
            new_key = replacement[key]
            if new_key in present_keys and new_key != key:
                # Drop the old key line to avoid duplicate new keys.
                continue
            new_lines.append(indent + new_key + eq + rest)
            present_keys.add(new_key)
        else:
            new_lines.append(line)
    new_text = ''.join(new_lines)
    if new_text != text:
        with open(path, 'w', encoding='utf-8', errors='surrogateescape', newline='') as f:
            f.write(new_text)
        changed += 1

if changed == 0:
    sys.exit('no local override file needed renaming')
print('renamed keys in ' + str(changed) + ' local override file(s)')
